    # This assumes the base class or a specific subclass supports a .context attribute
    # If no explicit 'context' is in the source, this validates standard attribute assignment.
    exc = ParsingError("context test")
    exc.context = {"line": 10, "col": 5}
    assert exc.context["line"] == 10